from sage.all_cmdline import *   # import sage library

_sage_const_0 = Integer(0); _sage_const_1 = Integer(1); _sage_const_1024 = Integer(1024); _sage_const_2 = Integer(2); _sage_const_5 = Integer(5); _sage_const_4 = Integer(4); _sage_const_7 = Integer(7); _sage_const_3 = Integer(3); _sage_const_9 = Integer(9); _sage_const_946 = Integer(946); _sage_const_6407 = Integer(6407); _sage_const_10860 = Integer(10860); _sage_const_128 = Integer(128); _sage_const_104060 = Integer(104060); _sage_const_6 = Integer(6); _sage_const_1745370 = Integer(1745370); _sage_const_12145238 = Integer(12145238); _sage_const_44886481 = Integer(44886481); _sage_const_92943995 = Integer(92943995); _sage_const_102256019 = Integer(102256019); _sage_const_46709052 = Integer(46709052); _sage_const_16 = Integer(16); _sage_const_3784 = Integer(3784); _sage_const_57792 = Integer(57792); _sage_const_351019 = Integer(351019); _sage_const_1059230 = Integer(1059230); _sage_const_1587211 = Integer(1587211); _sage_const_944620 = Integer(944620); _sage_const_4515 = Integer(4515); _sage_const_5399 = Integer(5399); _sage_const_105 = Integer(105); _sage_const_22 = Integer(22); _sage_const_17 = Integer(17); _sage_const_11 = Integer(11); _sage_const_13 = Integer(13); _sage_const_19 = Integer(19); _sage_const_23 = Integer(23); _sage_const_29 = Integer(29); _sage_const_31 = Integer(31)
from sage.all import *
from ore_algebra import OreAlgebra

# Build M₁₆ over Q(t)
Rn = PolynomialRing(QQ, names=('n',)); (n,) = Rn._first_ngens(1)
Kn = Rn.fraction_field()
Rt = PolynomialRing(QQ, names=('t',)); (t,) = Rt._first_ngens(1)
Kt = Rt.fraction_field()
OD = OreAlgebra(Kt, 'Dt', names=('Dt',)); (Dt,) = OD._first_ngens(1)
theta = Kt(t)*Dt

def eval_poly_at_op(f, T):
    out = OD.zero()
    for a in reversed(Rn(f).list()):
        out = out*T + Kt(a)
    return out

def primitive_coefficients(c):
    c = [Kn(a) for a in c]
    den = Rn.one()
    for a in c:
        den = lcm(den, Rn(a.denominator()))
    nums = [Rn(den*a) for a in c]
    g = nums[_sage_const_0 ]
    for a in nums[_sage_const_1 :]:
        g = gcd(g, a)
    nums = [a.quo_rem(g)[_sage_const_0 ] for a in nums]
    scl = QQ(_sage_const_1 )/QQ(nums[-_sage_const_1 ].leading_coefficient())
    return [Rn(scl*a) for a in nums]

# Original P2.7 rational recurrence
def A(z): return _sage_const_1024 *(_sage_const_2 *z+_sage_const_5 )**_sage_const_4 *(_sage_const_2 *z+_sage_const_7 )**_sage_const_3 *(_sage_const_2 *z+_sage_const_9 )**_sage_const_3 *(_sage_const_946 *z**_sage_const_2 +_sage_const_6407 *z+_sage_const_10860 )
def B(z): return _sage_const_128 *(_sage_const_2 *z+_sage_const_7 )**_sage_const_3 *(_sage_const_2 *z+_sage_const_9 )**_sage_const_3 *(_sage_const_104060 *z**_sage_const_6 +_sage_const_1745370 *z**_sage_const_5 +_sage_const_12145238 *z**_sage_const_4 +_sage_const_44886481 *z**_sage_const_3 +_sage_const_92943995 *z**_sage_const_2 +_sage_const_102256019 *z+_sage_const_46709052 )
def C(z): return _sage_const_16 *(z+_sage_const_3 )**_sage_const_4 *(_sage_const_2 *z+_sage_const_9 )**_sage_const_3 *(_sage_const_3784 *z**_sage_const_5 +_sage_const_57792 *z**_sage_const_4 +_sage_const_351019 *z**_sage_const_3 +_sage_const_1059230 *z**_sage_const_2 +_sage_const_1587211 *z+_sage_const_944620 )
def D_coeff(z): return (z+_sage_const_3 )**_sage_const_4 *(z+_sage_const_4 )**_sage_const_6 *(_sage_const_946 *z**_sage_const_2 +_sage_const_4515 *z+_sage_const_5399 )

crat = [Kn(-D_coeff(n)/A(n)), Kn(C(n+_sage_const_1 )/A(n+_sage_const_1 )), Kn(-B(n+_sage_const_2 )/A(n+_sage_const_2 )), Kn(_sage_const_1 )]
p_coeff = primitive_coefficients(crat)

# Build Euler quotient M₁₆
Rx = PolynomialRing(QQ, names=('x',)); (x,) = Rx._first_ngens(1)
shifted = [Rx(p_coeff[j](x-j)) for j in range(_sage_const_4 )]
gshift = shifted[_sage_const_0 ]
for f in shifted[_sage_const_1 :]:
    gshift = gcd(gshift, f)
gshift = gshift.monic()
assert gshift == x**_sage_const_2  + QQ(_sage_const_105 )/_sage_const_22 *x + QQ(_sage_const_5399 )/_sage_const_946 

Rpoly = []
for f in shifted:
    q, rem = f.quo_rem(gshift)
    assert rem == _sage_const_0 
    Rpoly.append(q)

M16 = OD.zero()
for j in range(_sage_const_4 ):
    M16 += Kt(t**j)*eval_poly_at_op(Rpoly[j], -theta-_sage_const_1 )
assert M16.order() == _sage_const_16 
print(f"M16 order = {M16.order()}")

# Extract polynomial coefficients and clear denominators
coeffs_M16 = [M16[k] for k in range(_sage_const_17 )]
denom = Rt.one()
for c in coeffs_M16:
    c = Kt(c)
    denom = lcm(denom, Rt(c.denominator()))
int_coeffs = [Rt(denom * Kt(c)) for c in coeffs_M16]

# Scale to make everything integer-coefficient
# Find the overall lcm of all denominators of all polynomial coefficients
from fractions import Fraction
overall_denom = ZZ(_sage_const_1 )
for poly in int_coeffs:
    for coeff in poly.list():
        if coeff != _sage_const_0 :
            overall_denom = lcm(overall_denom, ZZ(QQ(coeff).denominator()))
int_coeffs_Z = [Rt([ZZ(QQ(c)*overall_denom) for c in poly.list()]) for poly in int_coeffs]
print(f"Cleared denominators (scale = {overall_denom})")
print(f"Coefficient degrees: {[c.degree() for c in int_coeffs_Z]}")

# Verify leading coefficient
lc = int_coeffs_Z[_sage_const_16 ]
print(f"Leading coeff degree = {lc.degree()}")

# P-curvature computation
# Work directly over F_p[t] with variable name 't' (not 'tp')
def p_curvature_mod(int_coeffs_Z, p_prime, verbose=True):
    """
    Compute D^p mod L in F_p(t)[D].
    Returns 0 if p-curvature vanishes, else the order of D^p mod L.
    """
    Fp = GF(p_prime)

    # Use a fresh polynomial ring over Fp with variable 's' to avoid name conflicts
    Rp = PolynomialRing(Fp, 's')
    s = Rp.gen()
    Kp = Rp.fraction_field()
    ODp = OreAlgebra(Kp, ('Ds', {}, {s: _sage_const_1 }))
    Ds = ODp.gen()

    d = len(int_coeffs_Z) - _sage_const_1   # order

    # Reduce coefficients mod p, substituting t -> s
    L_mod = ODp.zero()
    for k in range(d+_sage_const_1 ):
        coeffs_list = Rt(int_coeffs_Z[k]).list()
        poly_mod = sum(Fp(ZZ(c)) * s**i for i, c in enumerate(coeffs_list))
        L_mod += Kp(poly_mod) * Ds**k

    if L_mod == _sage_const_0 :
        if verbose:
            print(f"  p={p_prime}: operator ZERO mod p (bad prime)")
        return -_sage_const_1 

    if L_mod[d] == _sage_const_0 :
        if verbose:
            print(f"  p={p_prime}: leading coeff vanishes (bad prime)")
        return -_sage_const_1 

    # Compute D^p mod L using repeated squaring
    # D^p in the Ore algebra: use the algebra's power method
    if verbose:
        print(f"  p={p_prime}: computing Ds^{p_prime} mod L (order {d})...")

    # Method: iterative squaring of Ds, reducing mod L at each step
    # Represent power as binary
    result = ODp.one()  # Ds^0
    base = Ds           # Ds^1
    exp = p_prime

    while exp > _sage_const_0 :
        if exp % _sage_const_2  == _sage_const_1 :
            result = result * base
            if result.order() >= d:
                _, result = result.quo_rem(L_mod)
        exp //= _sage_const_2 
        if exp > _sage_const_0 :
            base = base * base
            if base.order() >= d:
                _, base = base.quo_rem(L_mod)

    if result == _sage_const_0 :
        if verbose:
            print(f"  p={p_prime}: Ψ_p = 0 ★ GLOBALLY NILPOTENT at this prime!")
        return _sage_const_0 
    else:
        pc_order = result.order()
        if verbose:
            print(f"  p={p_prime}: Ψ_p ≠ 0, order = {pc_order}")
        return pc_order

